      })
      .id('GrouoListDetail_Navi_onBackPressed_NavDestination')
      .backButtonIcon(this.isThemeActive ?
      new SymbolGlyphModifier($r('sys.symbol.chevron_backward')).fontColor([$r('app.color.skin_icon_primary')])
