              .maxLines(FontScaleState.isStandardGeer(this.fontSizeScale) ? 2 : 10)
              .constraintSize({ minHeight: '21vp' })
              .fontFamily('HarmonyHeiTi')
              .margin({
                bottom: $r('sys.float.padding_level1')
