        .type(ButtonType.Normal)
        .borderRadius(this.isPC ? $r('sys.float.corner_radius_level2') : 0)
        .width($r('app.float.id_card_image_mid'))
        .height($r('app.float.id_card_image_mid'))
        .buttonStyle(ButtonStyleMode.TEXTUAL)
        .stateEffect(true)
