    })
    .borderRadius($r('sys.float.ohos_id_corner_radius_menu'))
    .align(Alignment.Start)
    .backgroundColor($r('app.color.skin_ohos_id_color_list_card_bg'))
    .width('100%')
    .height($r('app.float.id_item_height_max'))
    .margin({ left: '4vp', right: '4vp' })
