  @Styles
  MenuItemStyles() {
    .padding({
      left: $r('app.float.id_card_margin_xl'),
      right: $r('app.float.id_card_margin_xl'),
    })
    .constraintSize({ minHeight: $r('app.float.id_item_height_mid') })
