    } catch (err) {
      HiLog.e(TAG, `getringToneAttrList  err :${err}`);
      return toneAttrsArr;
    }
    HiLog.i(TAG, `toneAttrsArr :${toneAttrsArr.length}`);
    return toneAttrsArr;
