                .maxLines(FontScaleState.isStandardGeer(this.fontSizeScale) ? 2 : 10)
            }
            .hitTestBehavior(HitTestMode.None)
            .justifyContent(FlexAlign.Center)
            .alignItems(HorizontalAlign.Start)
            .flexGrow(1)
