    clearInterval(this.ConnectTimer)
    this.connectConfirmDialogCtl.open()
    this.connectCount = Constants.CONNECT_COUNT
    this.ConnectTimer = setInterval(() => {
      this.connectCountDown()
    }, Constants.COUNTDOWN_INTERVAL);
