  setSelectDefault(disconnectFlag: boolean) {
    if (this.printer === undefined || disconnectFlag) {
      Log.info(TAG, 'setSelectDefault')
      this.currentPrinterSelection = SelectionModel.NO_Printer
      this.printerSelectArray = []
