        }
        .backgroundColor($r('app.color.default_background'))
        .width('100%')
        .height('100%')
      }
      .width('97%')
      .height('97%')
      .clip(true)
      .opacity(this.mOpacity)
      .borderRadius($r('app.float.default_border_radius'))
      .scale({
        x: this.mWidthSize,
        y: this.mHeightSize,
        z: 1,
        centerX: '100%',
        centerY: '0%'
      })
