    //init page state
    this.mOpacity = 0;
    this.mWidthSize = 0.7;
    this.mHeightSize = 0.7;

    //show animation
    animateTo({
      duration: 200,
      curve: Curve.Friction
    }, () => {
      this.mOpacity = 1;
      this.mWidthSize = 1.03;
      this.mHeightSize = 1.03;
