    }}, () => {
      this.componentOptAreaTranslateY = (-this.componentOptAreaHeightPX * 0.1) + 'px'
      this.backgroundOpacity = 0
      this.showComponentName = DropdownPanelComponentName.NONE
    })
  }

  _animateTo(config, callback) {
