    if (this.bannerOptions.duration != undefined) {
      this.duration = this.bannerOptions.duration
    }
    if (this.bannerOptions.vertical != undefined) {
      this.vertical = this.bannerOptions.vertical
    }
    if (this.bannerOptions.curve != undefined) {
      this.curve = this.bannerOptions.curve
    }
    if(this.bannerOptions.disableSwipe != undefined){
      this.disableSwipe = this.bannerOptions.disableSwipe
    }

    if (this.bannerOptions.bannerMargin != undefined) {
      this.bannerMargin = this.bannerOptions.bannerMargin
    }
    if (this.bannerOptions.animatedEnum != undefined) {
      this.animatedEnum = this.bannerOptions.animatedEnum
    }


    if(this.bannerOptions.animatedConfig != undefined){
      this.animatedConfig = this.bannerOptions.animatedConfig;
    }

  }

  userBannerData(){
    let tempTransforms = []
    for (let i = 0; i < this.data.length; i++) {
      tempTransforms.push('')
    }

    // 重置状态
    this.transforms = tempTransforms;

  }

  aboutToAppear() {

    this.userBannerConfig();

    this.userBannerData()
  }

  aboutToDisappear() {

  }

  watchBannerOptions() {
    this.userBannerConfig();
    this.resolveBoundValue();
  }

  watchUserData() {
    this.userBannerData()
  }

  build() {
    Swiper(this.swiperController) {
      ForEach(this.data, (item, index?: number) => {
        TransformerBanner(
          {
            data: $data,
            index: index,
            verticalMode: $vertical,
            bannerPreMargin: $bannerMargin,
            supportAnimatedEnum: $animatedEnum,
            transforms: $transforms,
            animatedConfig:$animatedConfig,
            bannerContent: (item, index) => {
              this.bannerContent(item, index)
            }
          })

      }
      )
    }
    .index(this.currentPosition)
    .prevMargin(this.bannerMargin.left)
    .nextMargin(this.bannerMargin.right)
    .autoPlay(this.autoPlay)
    .vertical(this.vertical)
    .disableSwipe(this.disableSwipe)

    .curve(this.curve)
    .duration(this.duration)
      // 优先考虑bool为false不设置情况, 如果bool设置true, 没有设置dot和dig则为bool值, bool设置了并且设置了dot或者dig以具体设置为准
    .indicator( (!this.indicator.dot && !this.indicator.dig)? this.indicator.bool: (this.indicator.dot? this.indicator.dot: this.indicator.dig))
    .interval(this.interval)
    .loop(this.loop)

    .onAreaChange((oldValue, newValue) => {
      this.swiperWidth = newValue.width as number
      this.swiperHeight = newValue.height as number
      this.resolveBoundValue();
    })


    .onChange((index: number) => {
      if(this.bannerOptions.onChange){
        this.bannerOptions.onChange(index);
      }
    })


    .onGestureSwipe((index: number, extraInfo: SwiperAnimationEvent) => {
      if(this.bannerOptions.onGestureSwipe){
        this.bannerOptions.onGestureSwipe(index,extraInfo);
      }
      if (!this.canRespTouch) {
        return
      }
      let offset = extraInfo.currentOffset;
      // offset > 0 左滑动, offset < 0 右滑动
      let touchIndex = index;

      let preIndex = 0;
      let nextIndex = 0;
      // 极限值处理
      if (touchIndex == 0) {
        preIndex = this.data.length - 1;
        nextIndex = touchIndex + 1;
      } else if (touchIndex == this.data.length - 1) {
        preIndex = touchIndex - 1;
        nextIndex = 0;
      } else {
        preIndex = touchIndex - 1;
        nextIndex = touchIndex + 1;
      }
      if (preIndex < 0) {
        preIndex = 0
      }
      if (preIndex > this.data.length - 1) {
        preIndex = this.data.length - 1
      }
      if (nextIndex < 0) {
        nextIndex = 0
      }
      if (nextIndex > this.data.length - 1) {
        nextIndex = this.data.length - 1
      }


      // 0的时候是当前页面正中心

      // 百分比为正 当前页面向左滑动

      let tempTransValue = new Array();
      // 百分比为负 当前页面向右滑动
      for (let i = 0; i < this.transforms.length; i++) {
        if (i == preIndex || i == nextIndex || i == touchIndex) {

          let itemWidth = this.swiperWidth;
          let itemHeight = this.swiperHeight;

          // 垂直模式
          if (this.vertical) {
            itemWidth = this.swiperHeight;
            itemHeight = this.swiperWidth;
          }

          tempTransValue[i] = {
            pageWidth: itemWidth,
            pageHeight: itemHeight,
            currentOffset: offset,

            targetOffset: 0,

            // 动画 开始index
            startIndex: 0,
            // 动画 结束index
            targetIndex: 0,

            // 动画结束目标前一个PreIndex
            targetPreIndex: 0,
            // 动画结束目标后一个nextIndex
            targetNextIndex: 0,

            // 触摸当前Index
            touchIndex: touchIndex,
            // 触摸前一个PreIndex
            touchPreIndex: preIndex,
            // 触摸后一个nextIndex
            touchNextIndex: nextIndex,
            bannerDuration: this.duration, // 动画效果过度时间
            bannerCurve: this.curve, // 动画插值器
            transformType: TransformType.GESTURE
          }
        } else {
          tempTransValue[i] = ''
        }
      }
      this.transforms = tempTransValue;
    })

    .onAnimationStart((index: number, targetIndex: number, extraInfo: SwiperAnimationEvent) => {
      if(this.bannerOptions.onAnimationStart){
        this.bannerOptions.onAnimationStart(index,targetIndex,extraInfo);
      }
      this.canRespTouch = false;
      let offset = extraInfo.currentOffset;
      let targetOffset = extraInfo.targetOffset
      // offset > 0 左滑动, offset < 0 右滑动
      let endIndex = targetIndex;
      let preIndex = 0;
      let nextIndex = 0;
      // 极限值处理
      if (endIndex == 0) {
        preIndex = this.data.length - 1;
        nextIndex = endIndex + 1;
      } else if (endIndex == this.data.length - 1) {
        preIndex = endIndex - 1;
        nextIndex = 0;
      } else {
        preIndex = endIndex - 1;
        nextIndex = endIndex + 1;
      }
      if (preIndex < 0) {
        preIndex = 0
      }
      if (preIndex > this.data.length - 1) {
        preIndex = this.data.length - 1
      }
      if (nextIndex < 0) {
        nextIndex = 0
      }
      if (nextIndex > this.data.length - 1) {
        nextIndex = this.data.length - 1
      }
      // 0的时候是当前页面正中心
      // 百分比为正 当前页面向左滑动
      let tempTransValue = new Array();
      // 百分比为负 当前页面向右滑动
      for (let i = 0; i < this.transforms.length; i++) {
        if (i == preIndex || i == nextIndex || i == endIndex) {

          let itemWidth = this.swiperWidth;
          let itemHeight = this.swiperHeight;
          // 垂直模式
          if (this.vertical) {
            itemWidth = this.swiperHeight;
            itemHeight = this.swiperWidth;
          }
          tempTransValue[i] = {
            pageWidth: itemWidth,
            pageHeight: itemHeight,
            currentOffset: offset,
            targetOffset: targetOffset,
            // 动画 开始index
            startIndex: index,
            // 动画 结束index
            targetIndex: targetIndex,
            // 动画结束目标前一个PreIndex
            targetPreIndex: preIndex,
            // 动画结束目标后一个nextIndex
            targetNextIndex: nextIndex,
            // 触摸当前Index
            touchIndex: 0,
            // 触摸前一个PreIndex
            touchPreIndex: 0,
            // 触摸后一个nextIndex
            touchNextIndex: 0,
            bannerDuration: this.duration, // 动画效果过度时间
            bannerCurve: this.curve, // 动画插值器
            transformType: TransformType.ANIMATE
          }
        } else {
          tempTransValue[i] = ''
        }

      }
      this.transforms = tempTransValue;
    })

    .onAnimationEnd((index: number, extraInfo: SwiperAnimationEvent) => {
      if(this.bannerOptions.onAnimationEnd){
        this.bannerOptions.onAnimationEnd(index,extraInfo);
      }
      this.canRespTouch = true;
    })
  }
}

