      }
      Row() {
        Text() {
          Span(this.backTitle)
          Span($r('app.string.access_permission'))
        }
        .fontSize(Constants.TEXT_SMALL_FONT_SIZE)
        .fontColor($r('sys.color.icon_secondary'))
        .fontWeight(FontWeight.Medium)
