import { componentUtils } from '@kit.ArkUI';
import { CommonConstant } from '../constant/CommonConstant';
import { DialogComponentOptions, PushDirection, TranslateOption } from '../controller/HMDialog';

@Component
export struct HMDialogComponent {
  @ObjectLink builder: DialogComponentOptions;
  @State translateOption: TranslateOption = new TranslateOption();
  private startWidthOrHeight: number = 0;

  aboutToAppear(): void {
    this.builder.translateOption = this.translateOption;
  }

  closeDialog(duration: number, animationCallback?: () => void) {
    animateTo({
      duration: duration, onFinish: () => {
        if (this.builder.componentContent) {
          this.getUIContext().getOverlayManager().removeComponentContent(this.builder.componentContent);
          this.builder.componentContent = null;
          this.builder.direction = null;
        }
      }
    }, () => {
      if (animationCallback) {
        animationCallback();
      }
      if (this.builder.direction === PushDirection.DOWN_TO_UP) {
        this.builder.translateOption!.y = '100%';
      } else if (this.builder.direction === PushDirection.RIGHT_TO_LEFT) {
        this.builder.translateOption!.x = '100%';
      } else if (this.builder.direction === PushDirection.LEFT_TO_RIGHT) {
        this.builder.translateOption!.x = '-100%';
      }
    });
  }

  build() {
    Column() {
      Column() {
        this.builder.customBuilder(this.builder.dataObj).builder(this.builder.dataObj, null);
      }
      .id('dialogColumn')
      .translate({ x: this.translateOption.x, y: this.translateOption.y })
      .gesture(
        PanGesture({ direction: PanDirection.All })
          .onActionStart(() => {
            if (this.builder.direction === PushDirection.DOWN_TO_UP) {
              this.startWidthOrHeight = px2vp(componentUtils.getRectangleById('dialogColumn').size.height);
            } else {
              this.startWidthOrHeight = px2vp(componentUtils.getRectangleById('dialogColumn').size.width);
            }
          })
          .onActionUpdate((event: GestureEvent) => {
            console.log('event.offsetX', event.offsetX);
            if (this.builder.direction === PushDirection.DOWN_TO_UP) {
              if (event.offsetY < 0) {
                this.builder.translateOption!.y = 0;
              } else {
                this.builder.translateOption!.y = event.offsetY;
              }
            } else if (this.builder.direction === PushDirection.LEFT_TO_RIGHT) {
              if (event.offsetX > 0) {
                this.builder.translateOption!.x = 0;
              } else {
                this.builder.translateOption!.x = event.offsetX;
              }
            } else if (this.builder.direction === PushDirection.RIGHT_TO_LEFT) {
              if (event.offsetX < 0) {
                this.builder.translateOption!.x = 0;
              } else {
                this.builder.translateOption!.x = event.offsetX;
              }
            }
          })
          .onActionEnd((event: GestureEvent) => {
            if (this.builder.direction === PushDirection.DOWN_TO_UP) {
              if (event.offsetY > this.startWidthOrHeight / 2) {
                // 关闭弹窗
                this.closeDialog(200, () => {
                  this.builder.translateOption!.y = this.startWidthOrHeight;
                });
              } else {
                // 还原弹窗
                animateTo({ duration: 200 }, () => {
                  this.builder.translateOption!.y = 0;
                });
              }
            } else if (this.builder.direction === PushDirection.LEFT_TO_RIGHT) {
              if (event.offsetX < -this.startWidthOrHeight / 2) {
                // 关闭弹窗
                this.closeDialog(200, () => {
                  this.builder.translateOption!.x = this.startWidthOrHeight;
                });
              } else {
                // 还原弹窗
                animateTo({ duration: 200 }, () => {
                  this.builder.translateOption!.x = 0;
                });
              }
            } else if (this.builder.direction === PushDirection.RIGHT_TO_LEFT) {
              if (event.offsetX > this.startWidthOrHeight / 2) {
                // 关闭弹窗
                this.closeDialog(200, () => {
                  this.builder.translateOption!.x = this.startWidthOrHeight;
                });
              } else {
                // 还原弹窗
                animateTo({ duration: 200 }, () => {
                  this.builder.translateOption!.x = 0;
                });
              }
            }
          })
      );
    }
    .width(CommonConstant.FULL_PERCENT_WIDTH)
    .height(CommonConstant.FULL_PERCENT_HEIGHT)
    .onClick(() => {
      this.closeDialog(350);
    })
    .justifyContent(this.builder.direction === PushDirection.DOWN_TO_UP ? FlexAlign.End : FlexAlign.Start)
    .alignItems(this.builder.direction === PushDirection.RIGHT_TO_LEFT ? HorizontalAlign.End : HorizontalAlign.Start);
  }
}

