import { CommonConstant } from "../constant/CommonConstant"
import { promptAction } from "@kit.ArkUI"
import { DialogComponentData } from "./DialogComponent"

@Component
export struct DoubleSpeed {
  @State speedNum: number = 0
  @State isSelected: number = 1
  @StorageLink('displayWidth') displayWidth: number = 0
  @State bindSheetOption: SheetOptions = {
    height: CommonConstant.SEVENTY_PERCENT_HEIGHT,
    showClose: false,
  }
  private clickSpeedDialogId: number = 0

  // @State clickSpeedOption: promptAction.ShowToastOptions = {
  //   // message: `已切换至${AppStorage.get('speedNum') as number}倍速播放`
  //   message: `已切换至${this.speedNum}倍速播放`
  // }
  @Builder
  clickSpeedBuilder() {
    Column() {
      Text(`已开启${this.speedNum}x倍速`)
    }
    // .translate({y:this.displayWidth < CommonConstant.PHONE_WIDTH ? -250 : -20})
    .width('100%')
    .height('100%')
    .backgroundColor(Color.Pink)
    .margin({ left: 10, right: 10 })
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
  }

  // @ObjectLink dialogComponentData: DialogComponentData;

  build() {
    RelativeContainer() {
      Flex({ direction: FlexDirection.Column, justifyContent: FlexAlign.SpaceEvenly }) {
        // 顶部文字
        Flex({ justifyContent:this.displayWidth > CommonConstant.PHONE_WIDTH &&
          this.displayWidth <= CommonConstant.FOLD_PHONE_WIDTH ? FlexAlign.Center : FlexAlign.SpaceBetween }) {
          Text(CommonConstant.DOUBLE_SPEED_TOP_TEXT)
            .fontWeight(CommonConstant.DOUBLE_SPEED_TEXT_FONT_WEIGHT)
            .fontSize(CommonConstant.DOUBLE_SPEED_TOP_TEXT_FONT_SIZE)
          Image(CommonConstant.IMAGE_CLOSE)
            .width(CommonConstant.IMAGE_CLOSE_WIDTH)
            .visibility(this.displayWidth > CommonConstant.PHONE_WIDTH &&
              this.displayWidth <= CommonConstant.FOLD_PHONE_WIDTH ? Visibility.Hidden : Visibility.Visible)
            .onClick(() => {
              // this.dialogComponentData.hmSliderController.closeDialog()
            })
        }
        // .height(CommonConstant.THIRTY_PERCENT_WIDTH)
        // .padding(CommonConstant.RIGHT_MARGIN)


        // 倍速区
        Flex({ direction: FlexDirection.Row, justifyContent: FlexAlign.SpaceEvenly, alignItems: ItemAlign.Center }) {
          Row() {
            Image(CommonConstant.SPEED_IMAGE)
              .width(CommonConstant.SPEED_IMAGE_WIDTH)
          }
          .width(CommonConstant.TEN_PERCENT_WIDTH)
          .margin({ right: CommonConstant.RIGHT_MARGIN })

          Text(CommonConstant.DOUBLE_SPEED_TEXT)
            .width(CommonConstant.TWENTY_PERCENT_HEIGHT)
            .fontWeight(CommonConstant.DOUBLE_SPEED_TEXT_FONT_WEIGHT)
          Flex({ direction: FlexDirection.Row, justifyContent: FlexAlign.SpaceEvenly, alignItems: ItemAlign.Center }) {
            ForEach(CommonConstant.VIDEO_DOUBLE_SPEED, (item: number, commonIndex: number) => {
              Text(item + 'x')
                .textAlign(TextAlign.Center)
                .fontWeight(CommonConstant.CUSTOM_FONT_WEIGHT)
                .fontColor(this.isSelected == commonIndex ? CommonConstant.SPEED_TEXT_CLICK_FONT_COLOR :
                CommonConstant.SPEED_TEX_FONT_COLOR)
                .onClick(() => {
                  this.isSelected = commonIndex
                  if (this.isSelected == commonIndex) {
                    this.speedNum = item
                    console.log('---speedNum', this.speedNum)
                    console.log('---item', item)
                    console.log('---this.isSelected', this.isSelected)
                    console.log('---commonIndex', commonIndex)
                    // console.log('---弹窗', JSON.stringify(this.clickSpeedOption))
                    AppStorage.setOrCreate('speedNum', this.speedNum)
                  }
                  promptAction.openCustomDialog({
                    builder: () => this.clickSpeedBuilder(),
                    isModal: false,
                    width: this.displayWidth > CommonConstant.PHONE_WIDTH &&
                      this.displayWidth <= CommonConstant.FOLD_PHONE_WIDTH ?
                      200 :
                      300,
                    height: 35,
                    alignment: DialogAlignment.Center,
                    offset: { dx: 0, dy: this.displayWidth < CommonConstant.PHONE_WIDTH ? 20 : 250 },
                    backgroundColor: CommonConstant.SPEED_TEXT_CLICK_BACKGROUND,
                    cornerRadius: this.displayWidth > CommonConstant.PHONE_WIDTH &&
                      this.displayWidth <= CommonConstant.FOLD_PHONE_WIDTH ? 10 : '50%'
                  }).then((dialogId: number) => {
                    this.clickSpeedDialogId = dialogId
                  })
                  setTimeout(()=>{
                    promptAction.closeCustomDialog(this.clickSpeedDialogId)
                  },2000)
                  // promptAction.showToast(this.clickSpeedOption)
                })
            })
          }
          .width(CommonConstant.SEVENTY_PERCENT_WIDTH)
        }
        .width(CommonConstant.FULL_PERCENT_WIDTH)
        // .height(CommonConstant.THIRTY_PERCENT_WIDTH)
        .padding({ left: CommonConstant.RIGHT_MARGIN })

        // 举报
        Row() {
          Image(CommonConstant.REPORT_IMAGE)
            .width(CommonConstant.REPORT_IMAGE_WIDTH)
            .margin({ right: CommonConstant.REPORT_IMAGE_MARGIN })
          Text(CommonConstant.REPORT_TEXT)
            .fontWeight(CommonConstant.CUSTOM_FONT_WEIGHT)
        }
        .width(CommonConstant.FULL_PERCENT_WIDTH)
        // .height(CommonConstant.THIRTY_PERCENT_WIDTH)
        .padding({ left: CommonConstant.RIGHT_MARGIN })

        // 底部按钮
        if (this.displayWidth > CommonConstant.PHONE_WIDTH && this.displayWidth <= CommonConstant.FOLD_PHONE_WIDTH) {
          Button(CommonConstant.FOLD_DOUBLE_SPEED_BOTTOM_BUTTON_TEXT)
            .width(CommonConstant.NINETY_FIVE_PERCENT_WIDTH)
            .type(ButtonType.Normal)
            .borderRadius(CommonConstant.FOLD_DOUBLE_SPEED_BOTTOM_BUTTON_RADIUS)
            .backgroundColor(CommonConstant.LIVE_COMMENTS_REPLY_BACKGROUND_COLOR)
        }
      }
      .backgroundColor(CommonConstant.SPEED_BACKGROUND_COLOR)
      .width(this.displayWidth > CommonConstant.PHONE_WIDTH && this.displayWidth <= CommonConstant.FOLD_PHONE_WIDTH ?
      CommonConstant.SIXTY_PERCENT_WIDTH : CommonConstant.FULL_PERCENT_WIDTH)
      .height(CommonConstant.THIRTY_PERCENT_HEIGHT)
      // .translate({ y: this.dialogComponentData.y })
      .borderRadius({
        topLeft: this.displayWidth > CommonConstant.PHONE_WIDTH &&
          this.displayWidth <= CommonConstant.FOLD_PHONE_WIDTH ?
        CommonConstant.FOLD_DOUBLE_SPEED_BORDER_RADIUS : CommonConstant.DOUBLE_SPEED_TOP_BORDER_RADIUS,
        topRight: this.displayWidth > CommonConstant.PHONE_WIDTH &&
          this.displayWidth <= CommonConstant.FOLD_PHONE_WIDTH ?
        CommonConstant.FOLD_DOUBLE_SPEED_BORDER_RADIUS : CommonConstant.DOUBLE_SPEED_TOP_BORDER_RADIUS,
        bottomLeft: this.displayWidth > CommonConstant.PHONE_WIDTH &&
          this.displayWidth <= CommonConstant.FOLD_PHONE_WIDTH ?
        CommonConstant.FOLD_DOUBLE_SPEED_BORDER_RADIUS : CommonConstant.DOUBLE_SPEED_BOTTOM_BORDER_RADIUS,
        bottomRight: this.displayWidth > CommonConstant.PHONE_WIDTH &&
          this.displayWidth <= CommonConstant.FOLD_PHONE_WIDTH ?
        CommonConstant.FOLD_DOUBLE_SPEED_BORDER_RADIUS : CommonConstant.DOUBLE_SPEED_BOTTOM_BORDER_RADIUS,
      })
      .translate({
        x: this.displayWidth < CommonConstant.PHONE_WIDTH ? 0 : CommonConstant.FIFTY_PERCENT_WIDTH,
        y: this.displayWidth < CommonConstant.PHONE_WIDTH ? 0 : 100
      })
      .alignRules({
        bottom: {
          anchor: "__container__",
          align: this.displayWidth < CommonConstant.PHONE_WIDTH ? VerticalAlign.Bottom : VerticalAlign.Center
        },
        right: {
          anchor: "__container__",
          align: this.displayWidth < CommonConstant.PHONE_WIDTH ? HorizontalAlign.End : HorizontalAlign.Center
        }
      })
    }
  }
}

@Builder
export function DoubleSpeedBuilder() {
  DoubleSpeed()
}

