import { JSON, util } from '@kit.ArkTS';
import { window } from '@kit.ArkUI';
import { BusinessError } from '@kit.BasicServicesKit';
import { audio } from '@kit.AudioKit';
import { media } from '@kit.MediaKit';
import { HMSliderPlayerController } from '../controller/HMSliderPlayerController';
import {
  HMCustomSliderPlayerDataSource,
  HMSliderPlayerDataSource,
  HMSliderPlayerIDataSource,
  HMVideoSliderPlayerDataSource
} from '../datasource/HMSliderPlayerIDataSource';
import { CommonConstant } from '../constant/CommonConstant';
import { HMVideoSliderComponent } from './HMVideoSliderComponent';
import { Logger } from '../logger/Logger';
import { WindowMgr } from '../controller/WindowMgr';
import { AVPlayerState } from '../controller/interface';
import { HMAVPlayerMgr } from '../controller/HMAVPlayerMgr';
import { SliderPlayAttribute } from '../controller/HMDialog';

@Component
export struct HMSliderPlayer {
  @State curIndex: number = 0;
  @State foldStatus: number = 0;
  @State sliderPlayAttribute: SliderPlayAttribute = new SliderPlayAttribute();
  @State sliderPlayerDirection: SliderPlayerDirection = new SliderPlayerDirection();
  @State screenDirection: ScreenDirection = new ScreenDirection()
  @Link hmSliderPlayerController: HMSliderPlayerController;
  private readonly tag: string = 'HMSliderPlayer --'
  private datasource: HMSliderPlayerIDataSource = new HMSliderPlayerIDataSource();
  private swiperController: SwiperController = new SwiperController();
  private hmAVPlayerMgr: HMAVPlayerMgr = new HMAVPlayerMgr();
  private options?: HMSliderPlayerOptions;
  private windowMgr: WindowMgr = WindowMgr.getInstance();
  private swiperCachedCount: number = 1;

  aboutToAppear(): void {
    this.setCacheCount();
    this.hmSliderPlayerController?.set(this.hmAVPlayerMgr);
    this.hmSliderPlayerController?.set(this.sliderPlayAttribute);
    this.hmSliderPlayerController?.set(this.sliderPlayerDirection);
    this.windowMgr.setScreenDirection(this.screenDirection);
    WindowMgr.getInstance().setUIContext(this.getUIContext())
    window.getLastWindow(this.getUIContext().getHostContext(), (err: BusinessError, data) => {
      if (err.code) {
        Logger.error('%{public}s Failed to obtain the top window. Code: %{public}d, message: %{public}s', this.tag,
          err.code, err.message);
      }
      this.windowMgr.setWindowStage(data);
      this.windowMgr.registerOnWindowSizeChange((size: window.Size) => {
        Logger.info('%{public}s Register windowSizeChange', this.tag);
      })
    });
  }

  setCacheCount() {
    if (this.options?.cachedCount) {
      if (this.options.cachedCount > 3) {
        this.swiperCachedCount = 3;
      } else if (this.options.cachedCount < 1) {
        this.swiperCachedCount = 1;
      } else {
        this.swiperCachedCount = this.options.cachedCount;
      }
    } else {
      this.swiperCachedCount = 1;
    }
  }

  build() {
    Column() {
      Stack({ alignContent: Alignment.TopStart }) {
        Swiper(this.swiperController) {
          LazyForEach(this.datasource,
            (item: HMVideoSliderPlayerDataSource | HMCustomSliderPlayerDataSource, index: number) => {
              HMVideoSliderComponent({
                index: index,
                datasource: item,
                curIndex: this.curIndex,
                foldStatus: this.foldStatus,
                avPlayerCallback: this.options?.avPlayerCallback,
                hmAVPlayerMgr: this.hmAVPlayerMgr,
                hmSliderPlayerController: this.hmSliderPlayerController
              });
            }, (item: HMSliderPlayerDataSource) => util.generateRandomUUID(true));
        }
        .cachedCount(this.swiperCachedCount)
        .width(CommonConstant.FULL_PERCENT_WIDTH)
        .height(CommonConstant.FULL_PERCENT_HEIGHT)
        .vertical(true)
        .loop(false)
        .curve(Curve.Ease)
        .duration(CommonConstant.DURATION_TIME)
        .indicator(false)
        .backgroundColor(Color.Black)
        .disableSwipe(this.screenDirection.isFullScreen)
        .onChange((index: number) => {
          if (this.options?.swiperCallback?.onChange) {
            this.options.swiperCallback?.onChange(index);
          }
        })
        .onAnimationStart((index: number, targetIndex: number, extraInfo: SwiperAnimationEvent) => {
          this.curIndex = targetIndex;
          if (this.options?.swiperCallback?.onAnimationStart) {
            this.options.swiperCallback?.onAnimationStart(index, targetIndex, extraInfo);
          }
        })
        .onAnimationEnd((index: number, extraInfo: SwiperAnimationEvent) => {
          if (this.options?.swiperCallback?.onAnimationEnd) {
            this.options.swiperCallback?.onAnimationEnd(index, extraInfo);
          }
        })
        .onGestureSwipe((index: number, extraInfo: SwiperAnimationEvent) => {
          if (this.options?.swiperCallback?.onGestureSwipe) {
            this.options.swiperCallback?.onGestureSwipe(index, extraInfo);
          }
        })
        .customContentTransition(this.options?.swiperCallback?.customContentTransition)
        .onContentDidScroll((selectedIndex: number, index: number, position: number, mainAxisLength: number) => {
          if (this.options?.swiperCallback?.onContentDidScroll) {
            this.options.swiperCallback?.onContentDidScroll(selectedIndex, index, position, mainAxisLength);
          }
        });
      }
      .id('hmSliderPlayer')
      .width(this.sliderPlayAttribute.width)
      .height(this.sliderPlayAttribute.height)
      .position({ x: this.sliderPlayAttribute.positionX, y: this.sliderPlayAttribute.positionY })
    }
    .width(CommonConstant.FULL_PERCENT_WIDTH)
    .height(CommonConstant.FULL_PERCENT_HEIGHT)
    .alignItems(this.sliderPlayerDirection.horizontalAlign)
  }
}

/**
 * HMSliderPlayer的配置参数
 */
export class HMSliderPlayerOptions {
  cachedCount?: number;
  displaySlider?: boolean;
  avPlayerCallback?: AVPlayerCallback;
  swiperCallback?: SwiperCallback;
}

export class AVPlayerCallback {
  onStateChangeCallback?: (index: number, state: AVPlayerState, reason: media.StateChangeReason) => void;
  onTimeUpdateCallback?: (index: number, time: number) => void;
  onVideoSizeChangeCallback?: (index: number, width: number, height: number) => void;
  onErrorCallback?: (index: number, err: BusinessError) => void;
  onAudioInterruptCallback?: (index: number, event: audio.InterruptEvent) => void;
}

export class SwiperCallback {
  onChange?: (index: number) => void;
  onAnimationStart?: (index: number, targetIndex: number, extraInfo: SwiperAnimationEvent) => void;
  onAnimationEnd?: (index: number, extraInfo: SwiperAnimationEvent) => void;
  onGestureSwipe?: (index: number, extraInfo: SwiperAnimationEvent) => void;
  customContentTransition?: SwiperContentAnimatedTransition;
  onContentDidScroll?: (selectedIndex: number, index: number, position: number, mainAxisLength: number) => void;
}

export class SliderPlayerDirection {
  horizontalAlign: HorizontalAlign = HorizontalAlign.Start;
}

export class ScreenDirection {
  isFullScreen: boolean = false;
}

