import resourceManager from '@ohos.resourceManager';

@Entry
@Preview
@Component
struct MonitoringSample {
  @State btn_scan_text: Resource = $r('app.string.start_monitor');
  @State private edit_text_layout_hint: string = '';
  @State private edit_text_region_hint: string = '';
  @State edit_text_layout: string = '';
  @State edit_text_region: string = '';
  @State is_List: boolean = false;
  @State loading_rotate: number = 0;
  @State setting_visibility: Visibility = Visibility.None;
  @State list_visibility: boolean = false;
  @State search_setting_text: Resource = $r('app.string.expand_search_settings')
  @State private toast_open_bluetooth: string = '';
  //  @State beaconList: Array<Beacon> = new Array()
  @State private beaconManager: BeaconManager = BeaconManager.getInstanceForApplication()
  @State private countArray: Array<number> = []
  @State private count: number = 0
  @State private enterRegionText: string = ''
  @State private determineStateText: string = ''

  build() {
    Column() {

      Column() {

        TextInput({ placeholder: this.edit_text_layout_hint, text: this.edit_text_layout })
          .type(InputType.Normal)
          .placeholderColor(Color.Gray)
          .placeholderFont({ size: 48 })
          .margin({ bottom: 10 })
          .onChange((value: string) => {
            this.edit_text_layout = value;
          })
        TextInput({ placeholder: this.edit_text_region_hint, text: this.edit_text_region })
          .type(InputType.Normal)
          .placeholderColor(Color.Gray)
          .placeholderFont({ size: 48 })
          .margin({ bottom: 10 })
          .onChange((value: string) => {
            this.edit_text_region = value;
          })

      }.width('100%').alignItems(HorizontalAlign.Start).padding(20).visibility(this.setting_visibility)

      Button(this.search_setting_text)
        .onClick(() => this.onSearchSettingClick())
        .fontSize(18)
        .margin({ bottom: 10 })

      Stack() {
        Button(this.btn_scan_text)
          .onClick(() => this.onSearchClick())
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
        Image($r('app.media.ic_loading'))
          .width(30)
          .height('100%')
          .align(Alignment.Center)
          .markAnchor({ x: 30 + 10, y: 0 })
          .position({ x: '100%', y: 0 })
          .objectFit(ImageFit.Contain)
          .rotate({
            x: 0,
            y: 0,
            z: 1,
            centerX: '50%',
            centerY: '50%',
            angle: this.loading_rotate
          })
