    .height('100%')
  }

  private loadStrings() {
    resourceManager.getResourceManager().then(manager => {
      manager.getString($r('app.string.setting_layout')
      .id).then(text => {
        this.edit_text_layout_hint = text;
      })
      manager.getString($r('app.string.setting_region')
      .id).then(text => {
        this.edit_text_region_hint = text;
      })
