          this.mConversationCtrl.cbSelectedOnlyOneMsmItemOfMmsList.isRcs) {
            this.displayRcsFileSize()
          } else if (this.mConversationCtrl.mmsList[this.mConversationCtrl.mmsIndex].isMsm) {
