  cancelSelectState() {
    this.multiSelectFlag = Visibility.None;
    this.show = true;
    PanGestureUtil.refresh()
    this.mFavoriteCtrl.isClickMore = true;
    this.mFavoriteCtrl.resetSelectData();
    this.mFavoriteCtrl.resetMmsCount();
    this.mFavoriteCtrl.cancelCheckedAll();
