  }

  build() {
    Row() {
      if (this.mFavoriteCtrl.searchContent === '' ||
        (this.mFavoriteCtrl.searchContent !== '' && this.content.indexOf(this.mFavoriteCtrl.searchContent) == -1) ||
      GlobalContext.getContext().getObject('isFontNormal')) {
