        if (msg) {
          this.imgWidth = msg.width
          this.imgHeight = msg.height
        }
      })
      .priorityGesture(
        GestureGroup(GestureMode.Exclusive,
          TapGesture({ count: 2 })
            .onAction(() => {
            })
        )
      )
      .bindContextMenu(this.showMenu, this.longPressMenuBuild, {
        placement: Placement.BottomLeft,
