                        //All read and more
                        if (!this.mInfoMsgCtrl.isMultipleSelectState && this.mInfoMsgCtrl.showToolBar) {
                            Flex({ direction: FlexDirection.Row, alignItems: ItemAlign.Center }) {
                                //All read
                                Flex({
                                    direction: FlexDirection.Column,
