              md: { span: 12, offset: 0 }, lg: { span: 8, offset: 2 },
            });

            Column() {
            }
            .width('100%')
            .height('100%')
            .useSizeType({
              xs: { span: 0, offset: 12 }, sm: { span: 0, offset: 12 },
              md: { span: 0, offset: 12 }, lg: { span: 2, offset: 10 },
            })
          }
          .width('100%')
          .height('100%');
        }
        .width('100%')
