      }
      .size({ width: '100%' })

      Column() {
        if (this.menuSection?.getFooter()) {
          MenuGroupItemComponent({ menuGroup: this.menuSection?.getFooter() });
        }
      }
    }
    .visibility(this.uiRefresher.isVisible() ? Visibility.Visible : Visibility.None);
  }

