          })
          .visibility((this.uiRefresher.isVisible() && this.lazyHotSpotMenus.totalCount() > COUNT_EMPTY) ?
          Visibility.Visible : Visibility.None);
        }
      }
      .expandSafeArea([SafeAreaType.SYSTEM], [SafeAreaEdge.BOTTOM])
      .size({ width: RELATIVE_LENGTH })
    }
    .expandSafeArea([SafeAreaType.SYSTEM], [SafeAreaEdge.BOTTOM])
    .visibility((this.uiRefresher.isVisible() && this.lazyHotSpotMenus.totalCount() > COUNT_EMPTY) ?
    Visibility.Visible : Visibility.None);
