      return `${item?.toString()}${stateIconId}${item.index}`;
    })
  }

  @Styles
  normalStyles() {
    .backgroundColor(this.isHover ? $r('sys.color.interactive_hover') : Color.Transparent)
    .borderRadius($r('app.float.wh_value_20'))
