                TreeItem({
                  fileItem: item,
                  selectUri: $selectUri,
                  chooseItem: $chooseItem,
                  selectName: $selectName,
                  layer: 2,
                  folderList: $folderList,
                  fileList: $fileList,
                  isClickExpand: $isClickExpand
