  }

  @Builder
  buildListItemView() {
    Flex({ alignItems: ItemAlign.Center }) {
      Column() {
        Image(this.isShowThumbnail(this.fileItem) ? this.fileItem.thumbUri : this.fileItem.icon)
          .objectFit(this.isShowThumbnail(this.fileItem) ? ImageFit.Cover : ImageFit.Contain)
