            .zIndex(ZIndex.LEVEL10)
            .position({ x: $r('app.float.common_position24'), y: $r('app.float.common_position26') })
        }
        if (this.fileItem.mimeTypeObj?.isVideo() && this.isShowThumbnail(this.fileItem)) {
