};

@Component
struct DlpDialog {
  @State dlpProperty: dlpDataType = GlobalContext.load('dlpProperty') !== undefined ? GlobalContext.load('dlpProperty') : defaultDlpProperty;
  private acontext: Context = getContext(this);
