import { HMLifecycle, HMLifecycleContext, HMRouter, HMRouterMgr, IHMLifecycle } from '@hadss/hmrouter';
import { BaseContainerStyles, ButtonStyles, CaseDescriptor, LogContainer, NavBar, PageConstants } from 'ui_components';
import { RouterPageConstant } from '../../constants/PageConstants';

@HMLifecycle({ lifecycleName: 'SinglePageCaseLifecycle' })
@Observed
export class SinglePageCaseLifecycle implements IHMLifecycle {
  @Track pageParam: number = 0;

  onPrepare(ctx: HMLifecycleContext): void {
    const param = HMRouterMgr.getCurrentParam();
    if (typeof param === 'number') {
      this.pageParam = param;
    } else {
      this.pageParam = 0;
    }
  }
}


@HMRouter({ pageUrl: PageConstants.SINGLE_PAGE_CASE, singleton: true, lifecycle: 'SinglePageCaseLifecycle' })
@Component
export struct SinglePageCase {
  @State logString: string = '';
  @State lifecycle: SinglePageCaseLifecycle =
    HMRouterMgr.getCurrentLifecycleOwner()?.getLifecycle() as SinglePageCaseLifecycle;
  private buttonStyle: ButtonStyles = new ButtonStyles();
  private baseContentStyles: BaseContainerStyles = new BaseContainerStyles();

  build() {
    Flex({
      direction: FlexDirection.Column,
      justifyContent: FlexAlign.Start,
      alignItems: ItemAlign.Stretch,
    }) {
      NavBar({ title: RouterPageConstant.ROUTER_CASE7_TITLE });
      CaseDescriptor({
        desc: RouterPageConstant.ROUTER_CASE7_DESC
      });
      LogContainer({ logString: `${RouterPageConstant.ROUTER_CASE7_LOG1}`+
        `${this.lifecycle.pageParam}${RouterPageConstant.ROUTER_CASE7_LOG2}` });
      Blank().layoutWeight(1);
      Button(RouterPageConstant.ROUTER_CASE7_BUTTON).attributeModifier(this.buttonStyle).onClick(() => {
        HMRouterMgr.push({ pageUrl: PageConstants.SINGLE_PAGE_CASE, param: this.lifecycle.pageParam + 1 });
      });
    }.attributeModifier(this.baseContentStyles);
  }
}

