        .maxLines(CommonConstants.TEXT_MAX_LINES)
        .textOverflow({ overflow: TextOverflow.Ellipsis });

      Row() {
        Row() {
          Image(this.item.userIcon)
            .width($r('app.float.image_size_16'))
