      LazyForEach(this.sourceData, (item: string, index: number) => {
        NodeContainerProxy({
          nodeItem: nodePoolVideo.getAVPlayerXComponentNode(
            {
              url: item,
              controller: videoData[index].controller,
              avPlayer: videoData[index].avPlayer,
              curIndex: this.curIndex,
              index: index,
            }, videoItemWrapper)
        })
      }, (item: string, index: number) => JSON.stringify(item) + index)
    }
    .cachedCount(3)
    .width('100%')
    .height('100%')
    .vertical(true)
    .loop(true)
    .curve(Curve.Ease)
    .duration(300)
    .indicator(false)
    .backgroundColor(Color.Black)
    .onAnimationStart((index: number, targetIndex: number, extraInfo: SwiperAnimationEvent) => {
      Logger.debug(TAG, `onAnimationStart index: ${index}, targetIndex: ${targetIndex}, extraInfo: ${extraInfo}.`);
      this.curIndex = targetIndex;
    })
    .onAnimationEnd((index: number, extraInfo: SwiperAnimationEvent) => {
      Logger.debug(TAG, `onAnimationEnd index: ${index}, extraInfo: ${extraInfo}.`);
    })
  }
}

