import { display, window } from '@kit.ArkUI';
import { AVDataSource } from '../viewmodel/AVDataSource';
import { CommonConstants } from '../constants/CommonConstants';
import { CustomNodePoolFactory, NodeContainerProxy, NodeItem, TypeReuseConfig } from '@hadss/nodepool';
import Logger from '../utils/Logger';
import { VideoPlayCmpView } from '../view/VideoPlayCmpView';

const TAG = '[ShortVideoCmpPage]';
const REUSE_VIEW_TYPE_VIDEO: string = 'reuse_video_type_';
let factoryVideo: CustomNodePoolFactory = new CustomNodePoolFactory();
let nodePoolVideo = factoryVideo.getCommonNodePool();
let playerItemWrapper: WrappedBuilder<ESObject> = wrapBuilder<ESObject>(playerBuilderCached);

export let gIndex: number = 0;

@Entry
@Component
struct ShortVideoCmpPage {
  @State curIndex: number = 0;
  @State firstFlag: boolean = true;
  @StorageLink('PageShowKey') isPageShow: boolean = false;
  @StorageLink('PageIndexKey') index: number = 0;
  @StorageProp(CommonConstants.UI_CONTEXT_STORAGE_KEY) uiContext: UIContext =
    AppStorage.get(CommonConstants.UI_CONTEXT_STORAGE_KEY) as UIContext;
  @State foldStatus: number = 0;
  @Provide isFirstAVPlayer: boolean = true;
  private swiperController: SwiperController = new SwiperController();
  private typeCfg: TypeReuseConfig = {
    type: REUSE_VIEW_TYPE_VIDEO,
    expirationTime: 60 * 60 * 1000,
    reuseCallback: this.reuseCallback,
    recycleCallback: this.recycleCallback
  }
  private sourceData = new AVDataSource(CommonConstants.VIDEO_SOURCE);

  async aboutToAppear(): Promise<void> {
    nodePoolVideo.setTypeReuseConfig(this.typeCfg);
    nodePoolVideo.setUiContext(this.uiContext);
    let context = this.uiContext.getHostContext();
    if (context) {
      let windowClass = await window.getLastWindow(context);
      windowClass.setWindowKeepScreenOn(true);
    } else {
      Logger.error(TAG, 'Host context is undefined.');
    }
    display.on('foldStatusChange', (foldStatus: display.FoldStatus) => {
      this.foldStatus = foldStatus;
      Logger.debug(TAG, `FoldStatusChange:${this.foldStatus}.`);
    })
  }

  async onPageHide(): Promise<void> {
    Logger.debug(TAG, `onPageHide curIndex: ${this.curIndex}`);
    this.isPageShow = false;
    let context = this.uiContext.getHostContext();
    if (context) {
      let windowClass = await window.getLastWindow(context);
      windowClass.setWindowSystemBarProperties({
        statusBarContentColor: '#000000'
      });
    } else {
      Logger.error(TAG, 'Host context is undefined.');
    }
  }

  async onPageShow(): Promise<void> {
    Logger.debug(TAG, `onPageShow curIndex: ${this.curIndex}`);
    this.isPageShow = true;
    let context = this.uiContext.getHostContext();
    if (context) {
      let windowClass = await window.getLastWindow(context);
      windowClass.setWindowSystemBarProperties({
        statusBarContentColor: '#FFFFFF'
      });
    } else {
      Logger.error(TAG, 'Host context is undefined.');
    }
  }

  build() {
    Swiper(this.swiperController) {
      LazyForEach(this.sourceData, (item: string, index: number) => {
        NodeContainerProxy({
          nodeItem: nodePoolVideo.getNode(
            REUSE_VIEW_TYPE_VIDEO,
            {
              curSource: item,
              curIndex: this.curIndex,
              index: index,
              foldStatus: this.foldStatus,
              isActivate: true,
            },
            playerItemWrapper)
        })
      }, (item: string, index: number) => JSON.stringify(item) + index)
    }
    .cachedCount(0)
    .width('100%')
    .height('100%')
    .vertical(true)
    .loop(true)
    .curve(Curve.Ease)
    .duration(300)
    .indicator(false)
    .backgroundColor(Color.Black)
    .onAnimationStart((index: number, targetIndex: number, extraInfo: SwiperAnimationEvent) => {
      Logger.debug(TAG, `onAnimationStart index: ${index}, targetIndex: ${targetIndex}, extraInfo: ${extraInfo}.`);
      this.curIndex = targetIndex;
      gIndex = this.curIndex;
    })
    .onAnimationEnd((index: number, extraInfo: SwiperAnimationEvent) => {
      Logger.debug(TAG, `onAnimationEnd index: ${index}, extraInfo: ${extraInfo}.`);
    })
  }

  private reuseCallback(item: NodeItem): void {
    Logger.debug(TAG, `reuseCallback in, url:${item?.data?.curSource}`);
  }

  private recycleCallback(item: NodeItem): void {
    Logger.debug(TAG, `recycleCallback in, url:${item?.data?.curSource}`);
    item!.data!.curIndex = -1;
    item!.data!.isActivate = false;
  }
}

@Builder
export function playerBuilderCached(data: ESObject) {
  Column() {
    VideoPlayCmpView({
      curSource: data.curSource,
      curIndex: data.curIndex,
      index: data.index,
      foldStatus: data.foldStatus,
      isActivate: data.isActivate,
    })
  }
}

