    onRangeSeekBarValuesChanged: (minValue, maxValue) => {
      // TODO 视频裁剪 和 预览的时间范围
      console.log("dodo RangSeekBarListener minValue=" + minValue + "  maxValue=" + maxValue)
      this.pause()
