    },
    onRangeSeekBarScrollChanged: (startPos, endPos) => {
      console.log("dodo RangSeekBarListener onRangeSeekBarScrollChanged startPos=" + startPos + "  endPos=" + endPos)
      let videoThumbs = this.mVideoThumbOption.videoThumbs
      if(videoThumbs == undefined){
        for (let i =0; i<this.mDuration; i= i+1000){
          let temp = new ThumbContent();
          if(this.videoTrimmerOption.framePlaceholder){
            temp.framePlaceholder = this.videoTrimmerOption.framePlaceholder
          }
          if(this.videoTrimmerOption.frameBackground){
            temp.frameBackground = this.videoTrimmerOption.frameBackground
          }
          videoThumbs.push(temp)
        }
      }



      let that = this
      console.log('dodo that.MAX_COUNT_RANGE =' + that.MAX_COUNT_RANGE)
      let reqStartPos = 0;
      for (let i = startPos; i <= endPos; i = i + 1) {
        if (i<videoThumbs.length && videoThumbs[i] && !videoThumbs[i].pixelMap) {
          reqStartPos = i;
          break;
        } else {
          continue;
        }
      }

      if (reqStartPos > 0) {

        that.videoTrimmerOption.loadFrameListener.onStartLoad()
        let reqCount = endPos - reqStartPos + 1;
        let count = 0;
        // 请求新的帧数据
        var frameCallBack: IFrameCallBack = {
          async callBackResult(data: ArrayBuffer, timeUs: number) {
            const imageSource = image.createImageSource(data)

            let videoThumbWidth = vp2px((that.mSeekBarWidth - 2 * that.THUMB_WIDTH) / that.MAX_COUNT_RANGE)
            let videoThumbHeight = vp2px(that.mSeekBarHeight)

            let decodingOptions = {
              sampleSize: 1,
              editable: true,
              desiredSize: { width: videoThumbWidth, height: videoThumbHeight },
              desiredPixelFormat: image.PixelMapFormat.RGBA_8888
            }

            imageSource.createPixelMap(decodingOptions).then(px => {
              let second = timeUs / 1000000
              console.log('dodo second=' + second + ' timeUs=' + timeUs)
              videoThumbs[second].pixelMap = px;
              that.updateList(videoThumbs)
              count++;
              if (count == reqCount) {
                that.videoTrimmerOption.loadFrameListener.onFinishLoad()
              }

              imageSource.release();

            })
          }
        }
        let startTime = reqStartPos * 1000000 + ''
        let endTime = endPos * 1000000 + ''
        MP4Parser.getFrameAtTimeRang(startTime, endTime, MP4Parser.OPTION_CLOSEST, frameCallBack)
      }
    }
  }
