    }.width('100%')
    .height('100%')
    .backgroundColor(Color.Black)
  }

  @Builder
  private videoContent() {
    Stack({ alignContent: Alignment.Center }) {

      XComponent({
        id: 'componentId',
        type: 'surface',
        controller: this.mXcomponentController
      })
        .onLoad(async () => {
          this.isLoaded = true;
          // 加载完成后调用初始化播放器函数
          if (this.onReadNext) {
            this.onReadNext();
            this.onReadNext = undefined
          }
        })
        .aspectRatio(this.ratio)
    }
    .onAreaChange((oldValue, newValue) => {
      this.mVideoParentWidth = newValue.width as number;
      this.mVideoParentHeight = newValue.height as number;
    })

    .width('100%')
    .height('70%')
  }

  @Builder
  private bottomContent() {
    Column() {
      // Text(`拖动选择你要发表的${this.VIDEO_MAX_TIME}秒以内片段`)
      Text(this.hintText)
        .fontColor(Color.White)
        .height(20)
      this.userSelectContent()
      this.bottomClickContent()
    }
    .alignItems(HorizontalAlign.Center)

    .width('100%')
    .height('30%')
  }

  @State isPausePreview: boolean = true;

  @Builder
  private bottomClickContent() {
    Flex({ justifyContent: FlexAlign.SpaceBetween, alignItems: ItemAlign.Center }) {
      Text($r('app.string.trim_view_cancel'))
        .fontColor(Color.White)
        .textAlign(TextAlign.Center)
        .width(80)
        .height(40)

        .onClick(() => {
          if (this.videoTrimmerOption) {
            this.releaseAvPlayer().then(()=>{
              this.videoTrimmerOption.listener.onCancel()
            }).catch(err=>{
              console.log('VideoTrimmerView onCancel avplayer.stop() Or avplayer.release() err=' + err.message)
              this.videoTrimmerOption.listener.onCancel()
            })
          }
        })

      Image(this.isPausePreview ? $r('app.media.ic_video_play_black') : $r('app.media.ic_video_pause_black'))
        .height(40)
        .width(40)
        .objectFit(ImageFit.Contain)
        .onClick(() => {
          // 改变状态
          this.isPausePreview = !this.isPausePreview

          if (this.isPausePreview) {
            //  暂停
            this.mMediaPlayerStatus = {
              isPlaying: false,
              redLineProgress: this.mRedProgressBarPos
            }
            // 暂停视频播放
            this.pause();
          } else {
            // 开始预览视频
            this.play();
          }


        })

      Text($r('app.string.trim_view_finish'))
        .fontColor($r('app.color.trim_view_finish_color'))
        .textAlign(TextAlign.Center)
        .width(80)
        .height(40)

        .onClick(() => {
          if (this.isTrimming) {
            return
          }
          this.isTrimming = true;
          if (this.videoTrimmerOption) {
            this.videoTrimmerOption.listener.onStartTrim()
          }
          let sTime = msToHHMMSS(this.startTruncationTime)
          let eTime = msToHHMMSS(this.endTruncationTime)
          let srcFilePath = this.videoTrimmerOption.srcFilePath
          let outFilePath = getContext(this).cacheDir + '/trimmedVideo_' + (new Date().getTime()) + '.mp4';

          let that = this
          let callback: ICallBack = {
            callBackResult(code: number) {
              if (code == 0) {
                if (that.videoTrimmerOption) {

                  that.releaseAvPlayer().then(()=>{
                    that.videoTrimmerOption.listener.onFinishTrim(outFilePath)
                  }).catch(err=>{
                    console.log('VideoTrimmerView onFinishTrim avplayer.stop() Or avplayer.release() err=' + err.message)
                  })
                }
              }
            }
          }
          MP4Parser.videoClip(sTime, eTime, srcFilePath, outFilePath, callback)
        })
    }
    .width('100%')
    .height('50%')
  }

  @Builder
  private userSelectContent() {
    Stack() {
      Column() {
        // 为了保持一致
        Stack() {
        }
        .width('100%')
        .height('15%')

        VideoThumbListView({ scroller: this.scroller, mVideoThumbOption: $mVideoThumbOption })
          .width('100%')
          .height('85%')

      }.margin({ left: this.THUMB_WIDTH, right: this.THUMB_WIDTH })

      RangeSeekBarView({ scroller: this.scroller,
        mRangSeekBarOption: $mRangSeekBarOption,
        mMediaPlayerStatus: $mMediaPlayerStatus,
        mRangSeekBarListener: $mRangSeekBarListener
      })
        .width('100%')
        .height('100%')
        .onAreaChange((oldValue, newValue) => {
          this.mSeekBarWidth = newValue.width as number;
          this.mSeekBarHeight = newValue.height as number;
          this.configUIInfo()
        })
    }
    .width('100%')
    .height('50%')
  }

  videoPrepared() {
    // 提示语设置
    this.hintText = this.getFormatString($r('app.string.trim_view_hint').id, `${this.VIDEO_MAX_TIME}`)
    // 宽高比 设置
    let videoWidth = this.avPlayer.width;
    let videoHeight = this.avPlayer.height;
    this.ratio = videoWidth * (1.0) / videoHeight
    console.log('dodo this.ratio=' + this.ratio)


    // 设置当前Video 总时长
    this.mDuration = this.avPlayer.duration;

    // 默认的截取时间段[0-Nath.min(VIDEO_MAX_TIME,mDuration)]
    this.startTruncationTime = 0;
    this.endTruncationTime = Math.min(this.VIDEO_MAX_TIME * 1000, this.mDuration)

    if (!this.getRestoreState()) {
      this.seekTo(this.mRedProgressBarPos)
    } else {
      this.setRestoreState(false);
      this.seekTo(this.mRedProgressBarPos)
    }
    this.initList()
    this.initRangeSeekBarView();
  }

  initList() {
    let videoThumbs = []
    for (let i = 0; i < this.mDuration; i = i + 1000) {
      let temp = new ThumbContent();

      if (this.videoTrimmerOption.framePlaceholder) {
        temp.framePlaceholder = this.videoTrimmerOption.framePlaceholder
      }
      if (this.videoTrimmerOption.frameBackground) {
        temp.frameBackground = this.videoTrimmerOption.frameBackground
      }
      videoThumbs.push(temp)
    }

    let that = this
    let firstLoadMax = that.MAX_COUNT_RANGE
    if(that.mDuration/1000 < that.MAX_COUNT_RANGE){
       firstLoadMax = Math.ceil(that.mDuration/1000)
    }

    var callBack: ICallBack = {
      callBackResult(code: number) {
        if (code == 0) {
          let count = 0;

          var frameCallBack: IFrameCallBack = {
            async callBackResult(data: ArrayBuffer, timeUs: number) {
              const imageSource = image.createImageSource(data)

              let videoThumbWidth = vp2px((that.mSeekBarWidth - 2 * that.THUMB_WIDTH) / that.MAX_COUNT_RANGE)
              let videoThumbHeight = vp2px(that.mSeekBarHeight)

              let decodingOptions = {
                sampleSize: 1,
                editable: true,
                desiredSize: { width: videoThumbWidth, height: videoThumbHeight },
                desiredPixelFormat: image.PixelMapFormat.RGBA_8888
              }

              imageSource.createPixelMap(decodingOptions).then(px => {
                let second = timeUs / 1000000
                console.log('dodo second=' + second + ' timeUs=' + timeUs)
                videoThumbs[second].pixelMap = px;
                that.updateList(videoThumbs)
                count++
                if (count == firstLoadMax) {
                  that.videoTrimmerOption.loadFrameListener.onFinishLoad();
                }

                imageSource.release()

              })
            }
          }
          let startTime = 0 * 1000000 + ''
          let endTime = (firstLoadMax - 1) * 1000000 + ''
          MP4Parser.getFrameAtTimeRang(startTime, endTime, MP4Parser.OPTION_CLOSEST, frameCallBack)
        }
      }
    }
    this.videoTrimmerOption.loadFrameListener.onStartLoad();
    MP4Parser.setDataSource(this.videoTrimmerOption.srcFilePath, callBack)


    console.log("dodo initList list size=" + videoThumbs.length)
    this.updateList(videoThumbs)
  }

  updateList(videoThumbs: ThumbContent[]) {
    this.mVideoThumbOption = {
      videoThumbWidth: (this.mSeekBarWidth - 2 * this.THUMB_WIDTH) / this.MAX_COUNT_RANGE,
      videoThumbs: videoThumbs
    }
  }

  initRangeSeekBarView() {

    this.mRangSeekBarOption = {
      mLeftProgressPos: 0,
      mRightProgressPos: this.mDuration,
      // 最小时间 比如一屏幕10张图 间隔10s, 现在最小时间是3s,那么leftThumb和rightThumb的最小间隔是3张图宽度
      mMinShootTime: this.VIDEO_MIN_TIME,
      // 最大时间 约束了右侧thumb和左侧thumb的距离
      mMaxShootTime: this.VIDEO_MAX_TIME,

      // 一屏幕展示最大图片数量, 一张图是1s,如果最大数量是20, 最大时间是10s，那么 rightThumb 距离 leftThumb 就是屏幕的10/20
      // 需要保证mMaxCountRange <= mMaxShootTime 否则右侧的thumb会出界
      mMaxCountRange: this.MAX_COUNT_RANGE,


      mThumbWidth: this.THUMB_WIDTH,
      mPaddingTopBottom: this.PAD_LINE_WIDTH
    }
  }

  getRestoreState(): boolean {
    return this.isFromRestore;
  }

  seekTo(msec: number) {
    if(this && this.avPlayer) {
      this.avPlayer.seek(msec)
    }
  }

  setRestoreState(fromRestore: boolean) {
    this.isFromRestore = fromRestore;
  }

  getFormatString(resId: number, instead: string) {
    let resMgr = getContext(this).resourceManager
    try {
      let value = resMgr.getStringSync(resId)
      let values = value.split('%s')
      let ret = values[0] + instead + values[1]
      return ret
    } catch (error) {
      console.log('VideTrimmerView getFormatString has error msg:' + error.message)
    }
  }
}

