import { LottieView, LottieController, lottie } from '@ohos/lottie-turbo'
import common from '@ohos.app.ability.common'

@Entry
@Component
struct AsyncLoaderTest {
  @State isLoading: boolean = true
  @State animationPaths: string[] = []
  private controllers: LottieController[] = []
  private context = getContext(this) as common.UIAbilityContext

  async aboutToAppear() {
    try {
      // 获取资源管理器
      let resourceMgr = this.context.resourceManager
      // 获取指定目录下的文件列表
      let rawFiles = await resourceMgr.getRawFileList('common/rlottie')

      // 过滤出 .json 文件
      this.animationPaths = rawFiles
        .filter(file => file.endsWith('.json'))
        .map(file => `common/rlottie/${file}`)

      // 根据文件数量创建控制器
      this.controllers = Array(this.animationPaths.length)
        .fill(null)
        .map(() => new LottieController())

      this.isLoading = false

      lottie.resizeCache(100, 100 * 1024 * 1024);
      lottie.resizeFileCache(100, 100 * 1024 * 1024);
    } catch (error) {
      console.error('Failed to load animations:', error)
    }
  }

  aboutToDisappear() {
    this.controllers.forEach(controller => {
      controller?.stop()
      controller?.destroy()
    })
  }

  @Builder
  LoadingView() {
    Column() {
      LoadingProgress()
        .width(50)
        .height(50)
      Text('Loading...')
        .fontSize(14)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  getFileName(path: string): string {
    return path.split('/').pop()?.replace('.json', '') || ''
  }

  build() {
    Column() {
      Text('Queue Loader Test')
        .fontSize(24)
        .margin({ top: 20, bottom: 20 })

      if (this.isLoading) {
        this.LoadingView()
      } else {
        Scroll() {
          Grid() {
            ForEach(this.animationPaths, (path: string, index) => {
              GridItem() {
                Column() {
                  LottieView({
                    loop: true,
                    autoplay: true,
                    path: $rawfile(path),
                    controller: this.controllers[index],
                  })
                    .width('90%')
                    .aspectRatio(1)
                    .backgroundColor('#F1F3F5')
                    .margin(10)
                    .onClick(()=>{
                      this.controllers[index].play()
                    })
                  Text(this.getFileName(path))  // 显示文件名
                    .fontSize(14)
                    .margin({ top: 5, bottom: 5 })
                    .textAlign(TextAlign.Center)
                    .maxLines(2)
                    .textOverflow({ overflow: TextOverflow.Ellipsis })
                }
              }
            })
          }
          .columnsTemplate('1fr 1fr 1fr')  // 保持三列布局
          .width('100%')
          .layoutWeight(1)  // 使用layoutWeight替代固定高度
        }
        .scrollBar(BarState.Auto)
        .edgeEffect(EdgeEffect.Spring)
        .height('85%')
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

