import { lottie, LottieController, LottieListener, LottieView } from '@ohos/lottie-turbo';
import promptAction from '@ohos.promptAction';
import router from '@ohos.router';

@Entry
@Component
struct Cache {
  @State animation1Info: string = '动画1信息加载中...'
  @State animation2Info: string = '动画2信息加载中...'
  @State controlInfo: string = '控制信息加载中...'
  @State cacheSizeInput: string = '10' // rlottie默认缓存大小为10
  @State speedInput: string = '1' // 默认播放速度为1
  @State frameRateInput: string = '60' // 默认帧率为30
  // 每个动画的播放轮数统计
  @State totalPlayedCount1: number = 0
  @State totalPlayedCount2: number = 0
  // 缓存测试相关状态变量
  @State cacheEnabledTime: number = 0 // 缓存开启时的加载时间(ms)
  @State cacheDisabledTime: number = 0 // 缓存关闭时的加载时间(ms)
  @State timeDifference: string = this.getResourceString($r('app.string.not_tested')) // 时间差异
  @State testStatus: string = '缓存测试日志' // 测试状态信息
  @State isTesting: boolean = false // 是否正在测试
  @State currentTestIndex: number = 0 // 当前测试索引
  @State testPath: string = "https://cdn.lottielab.com/l/4Qj1ozX1JGqG6d.json" // 测试的动画路径
  @State testResults: string[] = [] // 测试结果记录
  @State showTestLottie: boolean = false // 控制是否显示测试用LottieView
  @State testAnimationPath: ResourceStr = '' // 测试动画资源路径
  @State showTestLottie1: boolean = false // 控制开启缓存的测试组件
  @State showTestLottie2: boolean = false // 控制关闭缓存的测试组件
  @State testStatus1: string = this.getResourceString($r('app.string.wait_test')) // 第一个测试状态
  @State testStatus2: string = this.getResourceString($r('app.string.wait_test')) // 第二个测试状态
  @State testFileName: string = ' ' // 显示用的文件名
  @State showCleaningProgress: boolean = false // 是否显示清理进度条
  @State cleaningProgress: number = 0 // 清理进度(0-100)
  @State cleaningStatus: string = this.getResourceString($r('app.string.prepare_to_clear_cache')) // 清理状态描述
  // 两个测试控制器
  private testController1: LottieController = new LottieController() // 开启缓存的控制器
  private testController2: LottieController = new LottieController() // 关闭缓存的控制器
  private testStartTime: number = 0
  // 测试监听器1
  private testListener1: LottieListener = new LottieListener({
    onDataReady: () => {
      const endTime = Date.now()
      const loadTime = endTime - this.testStartTime
      this.cacheEnabledTime = loadTime
      this.testStatus1 = `${this.getResourceString($r('app.string.cache_opened'))}: ${loadTime}ms`
      this.testResults.push(`${this.getResourceString($r('app.string.test'))} ${this.currentTestIndex +
        1} - ${this.getResourceString($r('app.string.open_cache'))}: ${loadTime}ms`)

      // 播放动画
      this.testController1.play()
      this.startSecondTest()
    }
  })

  // 开始第二次测试
  private startSecondTest() {
    this.showTestLottie2 = false
    this.testController2.destroy()

    setTimeout(() => {
      // 显示清理进度条
      this.showCleaningProgress = true
      this.cleaningProgress = 0
      this.cleaningStatus = this.getResourceString($r('app.string.prepare_to_test_disabling_cache'))

      // 清理进度
      let timer = setInterval(() => {
        this.cleaningProgress += 5

        // 根据进度更新状态描述
        if (this.cleaningProgress === 25) {
          this.cleaningStatus = this.getResourceString($r('app.string.cleaning_memory_cache'))
        } else if (this.cleaningProgress === 50) {
          this.cleaningStatus = this.getResourceString($r('app.string.cleaning_file_cache'))
        } else if (this.cleaningProgress === 75) {
          this.cleaningStatus = this.getResourceString($r('app.string.resetting_cache_settings'))
        }

        if (this.cleaningProgress >= 100) {
          clearInterval(timer)

          // 实际执行清理操作
          lottie.clearCache()
          lottie.clearFileCache()

          // 清理完成，隐藏进度条，开始第二次测试
          this.showCleaningProgress = false

          // 开始第二次测试
          setTimeout(() => {
            // 重新创建第二个控制器
            this.testController2 = new LottieController()

            // 设置第二个测试组件 - 确保缓存已关闭
            this.testStatus2 = this.getResourceString($r('app.string.testing_to_disable_cache_loading_time'))

            // 记录开始时间
            this.testStartTime = Date.now()

            // 显示第二个测试组件
            this.showTestLottie2 = true
          }, 200)
        }
      }, 100) // 每100ms增加5%，总共需要2秒完成
    }, 1000) // 第一个动画显示1秒后开始清理缓存
  }

  private testListener2: LottieListener = new LottieListener({
    onDataReady: () => {
      const endTime = Date.now()
      const loadTime = endTime - this.testStartTime
      this.cacheDisabledTime = loadTime
      this.testStatus2 = `${this.getResourceString($r('app.string.cache_closed'))}: ${loadTime}ms`
      this.testResults.push(`${this.getResourceString($r('app.string.test'))} ${this.currentTestIndex +
        1} - ${this.getResourceString($r('app.string.close_cache'))}: ${loadTime}ms`)

      // 计算差异并记录
      const diff = this.cacheDisabledTime - this.cacheEnabledTime
      this.timeDifference = `${this.getResourceString($r('app.string.open_cache_is_faster'))}: ${diff}ms (${diff > 0 ?
      this.getResourceString($r('app.string.difference')) :
        diff < 0 ? this.getResourceString($r('app.string.closing_cache_is_faster')) :
        this.getResourceString($r('app.string.no_difference'))})`
      this.testResults.push(`${this.getResourceString($r('app.string.test'))} ${this.currentTestIndex +
        1} - ${this.timeDifference}`)

      // 播放动画
      this.testController2.play()

      // 测试完成
      this.currentTestIndex++
      this.isTesting = false
    }
  })

  startTest() {
    if (this.isTesting) {
      return;
    }

    // 重置测试状态变量
    this.isTesting = true
    this.cacheEnabledTime = 0
    this.cacheDisabledTime = 0
    this.timeDifference = this.getResourceString($r('app.string.testing'))
    this.showTestLottie1 = false
    this.showTestLottie2 = false

    this.testStatus1 = this.getResourceString($r('app.string.wait_test'))
    this.testStatus2 = this.getResourceString($r('app.string.wait_test'))

    // 更彻底地清理资源
    this.testController1.destroy()
    this.testController2.destroy()

    // 显示清理进度条
    this.showCleaningProgress = true
    this.cleaningProgress = 0
    this.cleaningStatus = this.getResourceString($r('app.string.initializing_testing_environment'))

    // 模拟清理进度
    let timer = setInterval(() => {
      this.cleaningProgress += 5

      // 根据进度更新状态描述
      if (this.cleaningProgress === 25) {
        this.cleaningStatus = this.getResourceString($r('app.string.preparing_environment'))
      } else if (this.cleaningProgress === 50) {
        this.cleaningStatus = this.getResourceString($r('app.string.resetting_controller'))
      } else if (this.cleaningProgress === 75) {
        this.cleaningStatus = this.getResourceString($r('app.string.configuring_cache'))
      }

      if (this.cleaningProgress >= 100) {
        clearInterval(timer)

        // 清理完成，隐藏进度条，开始第一个测试
        this.showCleaningProgress = false

        // 延迟开始测试，确保UI更新
        setTimeout(() => {
          this.startActualTest()
        }, 200)
      }
    }, 100) // 每100ms增加5%，总共需要2秒完成
  }

  // 执行测试
  private startActualTest() {
    // 创建第一个测试组件
    this.testController1 = new LottieController()

    // 准备测试路径
    this.testAnimationPath = this.testPath
    this.testFileName = this.getFileName(this.testPath)

    // 设置第一个测试组件 - 开启缓存
    this.testStatus1 = this.getResourceString($r('app.string.testing_cache_loading_time_enabled'))

    // 记录开始时间
    this.testStartTime = Date.now()

    // 显示第一个测试组件
    this.showTestLottie1 = true
  }

  getFileName(path: string): string {
    if (!path) {
      return this.getResourceString($r('app.string.unknown_file'));
    }
    const parts = path.split('/')
    return parts[parts.length - 1]
  }

  getResourceString(res: Resource) {
    return getContext().resourceManager.getStringSync(res.id)
  }

  aboutToDisappear(): void {
    this.testController1.destroy();
    this.testController2.destroy();
  }

  build() {
    Column() {
      Scroll() {
        Column() {
          Column() {
            Text($r('app.string.cache_manager'))
              .fontSize(16)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 5 })

            Row() {
              TextInput({
                text: this.cacheSizeInput,
                placeholder: this.getResourceString($r('app.string.input_cache_size'))
              })
                .type(InputType.Number)
                .width('40%')
                .height(40)
                .margin({ right: 10 })
                .onChange((value) => {
                  this.cacheSizeInput = value;
                })

              Button($r('app.string.set_cache_size_button'))
                .onClick(() => {
                  try {
                    const size = parseInt(this.cacheSizeInput);
                    if (!isNaN(size) && size >= 0) {
                      promptAction.showToast({
                        message: `${this.getResourceString($r('app.string.cache_size_has_been_set_to'))} ${size}`
                      });
                    } else {
                      promptAction.showToast({
                        message: this.getResourceString($r('app.string.please_enter_a_valid_value'))
                      });
                    }
                  } catch (error) {
                    promptAction.showToast({
                      message: `${this.getResourceString($r('app.string.set_failed'))}: ${error instanceof Error ?
                      error.message : this.getResourceString($r('app.string.please_enter_a_valid_value'))}`
                    });
                  }
                })
            }
            .justifyContent(FlexAlign.Center)
            .margin({ bottom: 10 })
            .width('100%')

            Row() {
              Button($r('app.string.initialization_file_cache'))
                .onClick(() => {
                  try {
                    promptAction.showToast({ message: this.getResourceString($r('app.string.initialize_file_cache')) });
                  } catch (error) {
                    promptAction.showToast({
                      message: this.getResourceString($r('app.string.initialization_file_cache_failed'))
                    });
                  }
                })

              Button($r('app.string.reset_file_cache_size'))
                .onClick(() => {
                  const size = parseInt(this.cacheSizeInput);
                  if (!isNaN(size) && size > 0) {
                    lottie.resizeFileCache(size, 0);
                    promptAction.showToast({
                      message: `${this.getResourceString($r('app.string.file_cache_size_has_been_set_to'))}} ${size}`
                    });
                  } else {
                    promptAction.showToast({
                      message: this.getResourceString($r('app.string.please_enter_a_valid_value'))
                    });
                  }
                })
            }
            .margin({ bottom: 10 })
            .width('100%')
            .justifyContent(FlexAlign.SpaceAround)

            Row() {
              Button($r('app.string.clear_all_file_caches'))
                .onClick(() => {
                  lottie.clearFileCache();
                  promptAction.showToast({ message: this.getResourceString($r('app.string.cleared_all_file_caches')) });
                })

              Button($r('app.string.clear_individual_file_cache'))
                .onClick(() => {
                  lottie.clearFileCache(this.testPath);
                  promptAction.showToast({ message: this.getResourceString($r('app.string.cleared_file_cache')) });
                })
            }
            .margin({ bottom: 10 })
            .width('100%')
            .justifyContent(FlexAlign.SpaceAround)

            Row() {
              Button($r('app.string.clear_momery_cache'))
                .onClick(() => {
                  lottie.clearCache();
                  promptAction.showToast({ message: this.getResourceString($r('app.string.cache_cleared')) });
                })
            }.margin({ bottom: 10 })

            Row() {
              Button(this.getResourceString($r('app.string.delete_memory_cache_through_key')))
                .onClick(() => {
                  lottie.removeCache(this.testPath)
                })

              Button(this.getResourceString($r('app.string.reset_memory_cache_size')))
                .onClick(() => {
                  lottie.resizeCache(parseInt(this.cacheSizeInput), 1024 * 1024)
                })
            }

            Divider()
              .height(2)
              .color('#CCCCCC')
              .margin({ top: 20, bottom: 20 })

            Column() {
              Text(this.getResourceString($r('app.string.cache_performance_test_need_network')))
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 10 })

              Column() {
                Text(this.testStatus)
                  .fontSize(14)
                  .width('100%')
                  .textAlign(TextAlign.Center)
                  .padding(5)

                if (this.cacheEnabledTime > 0) {
                  Text(`${this.getResourceString($r('app.string.cache_open_load_time'))}: ${this.cacheEnabledTime}ms`)
                    .fontSize(14)
                    .width('100%')
                    .textAlign(TextAlign.Center)
                    .padding(5)
                }

                if (this.cacheDisabledTime > 0) {
                  Text(`${this.getResourceString($r('app.string.cache_disabled_load_time'))}: ${this.cacheDisabledTime}ms`)
                    .fontSize(14)
                    .width('100%')
                    .textAlign(TextAlign.Center)
                    .padding(5)
                }

                if (this.cacheEnabledTime > 0 && this.cacheDisabledTime > 0) {
                  Text(this.timeDifference)
                    .fontSize(14)
                    .fontWeight(FontWeight.Bold)
                    .width('100%')
                    .textAlign(TextAlign.Center)
                    .padding(5)
                }
              }
              .backgroundColor('#F0F0F0')
              .width('90%')
              .padding(10)
              .borderRadius(8)
              .margin({ bottom: 10 })

              Row() {
                Column() {
                  Text(this.getResourceString($r('app.string.cache_opened')))
                    .fontSize(14)
                    .fontWeight(FontWeight.Bold)
                    .margin({ bottom: 5 })

                  Text(this.testStatus1)
                    .fontSize(12)
                    .margin({ bottom: 5 })

                  if (this.showTestLottie1) {
                    LottieView({
                      loop: true,
                      autoplay: false,
                      contentMode: 'Contain',
                      frameRate: 30,
                      path: this.testAnimationPath,
                      controller: this.testController1,
                      listener: this.testListener1
                    })
                      .width('100%')
                      .height(120)
                      .backgroundColor('#E0E0E0')
                  } else {
                    Column() {
                      Text(this.getResourceString($r('app.string.wait_test')))
                        .fontSize(12)
                    }
                    .width('100%')
                    .height(120)
                    .backgroundColor('#E0E0E0')
                    .justifyContent(FlexAlign.Center)
                  }
                }
                .width('45%')

                Column() {
                  Text(this.getResourceString($r('app.string.cache_closed')))
                    .fontSize(14)
                    .fontWeight(FontWeight.Bold)
                    .margin({ bottom: 5 })

                  Text(this.testStatus2)
                    .fontSize(12)
                    .margin({ bottom: 5 })

                  if (this.showTestLottie2) {
                    LottieView({
                      loop: true,
                      autoplay: false,
                      contentMode: 'Contain',
                      frameRate: 30,
                      path: this.testAnimationPath,
                      controller: this.testController2,
                      listener: this.testListener2
                    })
                      .width('100%')
                      .height(120)
                      .backgroundColor('#E0E0E0')
                  } else {
                    Column() {
                      Text(this.getResourceString($r('app.string.wait_test')))
                        .fontSize(12)
                    }
                    .width('100%')
                    .height(120)
                    .backgroundColor('#E0E0E0')
                    .justifyContent(FlexAlign.Center)
                  }
                }
                .width('45%')
              }
              .width('90%')
              .margin({ bottom: 15 })
              .justifyContent(FlexAlign.SpaceBetween)

              Text(`${this.getResourceString($r('app.string.test_file'))}: ${this.testFileName}`)
                .fontSize(14)
                .width('90%')
                .margin({ bottom: 10 })

              if (this.cacheEnabledTime > 0 && this.cacheDisabledTime > 0) {
                Column() {
                  Text(`${this.getResourceString($r('app.string.open_cache'))}: ${this.cacheEnabledTime}ms | ${this.getResourceString($r('app.string.close_cache'))}: ${this.cacheDisabledTime}ms`)
                    .fontSize(14)
                    .width('100%')
                    .textAlign(TextAlign.Center)
                    .padding(5)

                  Text(this.timeDifference)
                    .fontSize(14)
                    .fontWeight(FontWeight.Bold)
                    .width('100%')
                    .textAlign(TextAlign.Center)
                    .padding(5)
                }
                .backgroundColor('#F0F0F0')
                .width('90%')
                .padding(10)
                .borderRadius(8)
                .margin({ bottom: 10 })
              }
              if (this.showCleaningProgress) {
                Column() {
                  Text(this.cleaningStatus)
                    .fontSize(14)
                    .fontWeight(FontWeight.Bold)
                    .margin({ bottom: 10 })

                  Progress({ value: this.cleaningProgress, total: 100 })
                    .width('90%')
                    .height(15)
                    .color('#4D80E6')

                  Text(`${this.cleaningProgress}%`)
                    .fontSize(12)
                    .margin({ top: 5, bottom: 10 })
                }
                .width('100%')
                .backgroundColor('#F0F0F0')
                .borderRadius(8)
                .padding(10)
                .margin({ bottom: 15 })
                .alignItems(HorizontalAlign.Center)
              }
              Button(this.isTesting ? this.getResourceString($r('app.string.testing')) :
              this.getResourceString($r('app.string.start_cache_test')))
                .width('60%')
                .enabled(!this.isTesting)
                .margin({ bottom: 10 })
                .onClick(() => {
                  this.showTestLottie1 = false
                  this.startTest()
                })

              if (this.testResults.length > 0) {
                Text($r('app.string.test_history'))
                  .fontSize(16)
                  .fontWeight(FontWeight.Bold)
                  .margin({ top: 10, bottom: 5 })

                List() {
                  ForEach(this.testResults, (result: string) => {
                    ListItem() {
                      Text(result)
                        .fontSize(14)
                        .padding(5)
                    }
                    .backgroundColor('#EEEEEE')
                    .borderRadius(5)
                    .margin({ bottom: 5 })
                  })
                }
                .width('90%')
                .height(150)
                .margin({ bottom: 10 })

                Button($r('app.string.clear_test_history'))
                  .width('60%')
                  .margin({ bottom: 20 })
                  .onClick(() => {
                    this.testResults = []
                    this.currentTestIndex = 0
                  })
              }
            }
            .width('100%')
            .alignItems(HorizontalAlign.Center)

            Column()
            Button($r('app.string.back_home'))
              .width('100%')
              .margin({ top: 10, bottom: 30 })
              .onClick(() => {
                router.back();
              })
          }
          .width('100%')
        }
        .width('90%')
        .alignItems(HorizontalAlign.Center)
      }
      .scrollBar(BarState.Auto)
      .scrollable(ScrollDirection.Vertical)
      .edgeEffect(EdgeEffect.Spring)
      .width('100%')
      .height('90%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor($r('sys.color.comp_background_list_card'))
  }
}

