        .titleMode(NavigationTitleMode.Mini)
        .backgroundColor("#fafafa")
      }
      .width("100%")
      .height("100%").justifyContent(FlexAlign.SpaceBetween)
    }
    .height('100%')
  }
}


@Component
struct MainSubMainPage {
  @State isRefreshing: boolean = false;
  @State isRefreshFinish: boolean = false;
  @State enterFrameText: string = "";
  @State enterFrameText2: string = "";
  private lottiecontroller: LottieController = new LottieController();
  private lottiecontroller2: LottieController = new LottieController();
  private listener: LottieListener = new LottieListener({
    onEnterFrame: () => {
      this.enterFrameText = this.lottiecontroller?.currentFrame?.toString();
    }
  })
  private listener2: LottieListener = new LottieListener({
    onEnterFrame: () => {
      this.enterFrameText2 = this.lottiecontroller2?.currentFrame?.toString();
    }
  })

  fakedRefreshList() {
    setTimeout(() => {
      this.isRefreshFinish = true;
      setTimeout(() => {
        this.isRefreshing = false;
        this.isRefreshFinish = false;
      }, 1000)
    }, 1000)
  }

  build() {
    Column() {
      Row() {
        LottieView({
          loop: true,
          autoplay: true,
          path: $rawfile('common/lottie/robotYoga.json'),
          controller: this.lottiecontroller,
          listener: this.listener,
          autoSkip: false
        })
          .width(100)
          .height(100)
          .visibility(this.isRefreshing ? Visibility.Visible : Visibility.None);

        LottieView({
          loop: true,
          autoplay: true,
          path: $rawfile('common/lottie/animation.json'),
          controller: this.lottiecontroller2,
          listener: this.listener2,
          autoSkip: true
        })
          .width(100)
          .height(100)
          .visibility(this.isRefreshing ? Visibility.Visible : Visibility.None);
      }.width(200)
      .height(100)


      Refresh({ refreshing: $$this.isRefreshing }) {
        ListPage({ enterFrameText: this.enterFrameText, enterFrameText2: this.enterFrameText2 })
      }
      .onRefreshing(() => {
        this.fakedRefreshList();
      })

    }

  }
}

